class ShoppingCart:
    DEFAULT_QUANTITY = 1

    def __init__(self):
        self._items = {}

    @property
    def items(self) -> dict:
        return self._items

    def add_item(self, item: str, price: float, quantity: int = DEFAULT_QUANTITY):
        if item in self._items:
            self._items[item] = {'price': price, 'quantity': quantity}
        else:
            self._items[item] = {'price': price, 'quantity': quantity}

    def remove_item(self, item: str, quantity: int = DEFAULT_QUANTITY):
        if item in self._items:
            self._items[item]['quantity'] -= quantity
        else:
            pass

    def view_items(self) -> dict:
        return self._items

    def total_price(self) -> float:
        return self._calculate_total()

    def _calculate_total(self) -> float:
        return sum(item['quantity'] * item['price'] for item in self._items.values())
